import os
from storage_client import get_s3_client


def create_presigned_download_url(payload, config=None):
    config = config or {}
    bucket_name = config.get("bucket", os.environ.get("AWS_S3_BUCKET_NAME"))
    object_name = payload["object_name"]
    expiration = payload.get("expiration", 3600)  # Default to 1 hour

    s3_client = get_s3_client(config.get("region"))

    try:
        response = s3_client.generate_presigned_url(
            'get_object',
            Params={'Bucket': bucket_name, 'Key': object_name},
            ExpiresIn=expiration
        )
        return {"presigned_url": response}
    except Exception as e:
        raise RuntimeError(f"Error generating presigned URL: {e}")

import os
from storage_client import get_s3_client


def get_object_metadata(payload, config=None):
    config = config or {}
    bucket_name = config.get("bucket", os.environ.get("AWS_S3_BUCKET_NAME"))
    object_name = payload["object_name"]

    s3_client = get_s3_client(config.get("region"))

    try:
        response = s3_client.head_object(Bucket=bucket_name, Key=object_name)
        # Extract relevant metadata, typically from the 'ResponseMetadata' and custom 'Metadata' fields
        metadata = {
            "content_type": response.get("ContentType"),
            "content_length": response.get("ContentLength"),
            "last_modified": response.get("LastModified").isoformat() if response.get("LastModified") else None,
            "etag": response.get("ETag"),
            "user_metadata": response.get("Metadata", {})
        }
        return metadata
    except s3_client.exceptions.ClientError as e:
        if e.response["Error"]["Code"] == "404":
            raise FileNotFoundError(f"Object {object_name} not found in bucket {bucket_name}")
        else:
            raise RuntimeError(f"Error retrieving object metadata: {e}")

import os
from storage_client import get_s3_client


def list_objects_with_prefix(payload, config=None):
    config = config or {}
    bucket_name = config.get("bucket", os.environ.get("AWS_S3_BUCKET_NAME"))
    prefix = payload.get("prefix", "")
    max_keys = payload.get("max_keys", 1000)  # Default max keys

    s3_client = get_s3_client(config.get("region"))

    try:
        response = s3_client.list_objects_v2(
            Bucket=bucket_name,
            Prefix=prefix,
            MaxKeys=max_keys
        )

        objects = []
        if "Contents" in response:
            for obj in response["Contents"]:
                objects.append({
                    "object_name": obj["Key"],
                    "last_modified": obj["LastModified"].isoformat(),
                    "etag": obj["ETag"],
                    "size": obj["Size"],
                    "storage_class": obj["StorageClass"]
                })
        return {"objects": objects, "is_truncated": response.get("IsTruncated", False)}
    except Exception as e:
        raise RuntimeError(f"Error listing objects with prefix: {e}")

import os
from storage_client import get_textract_client


def start_document_ocr(payload, config=None):
    config = config or {}
    bucket_name = config.get("bucket", os.environ.get("AWS_S3_BUCKET_NAME"))
    object_name = payload["object_name"]
    feature_types = payload.get("feature_types", ["FORMS", "TABLES"]) # Default to FORMS and TABLES

    textract_client = get_textract_client(config.get("region"))

    try:
        response = textract_client.start_document_analysis(
            DocumentLocation={
                'S3Object': {
                    'Bucket': bucket_name,
                    'Name': object_name
                }
            },
            FeatureTypes=feature_types
        )
        return {"job_id": response["JobId"]}
    except Exception as e:
        raise RuntimeError(f"Error starting Textract document analysis: {e}")

import os
from storage_client import get_translate_client


def translate_text_content(payload, config=None):
    config = config or {}
    text_to_translate = payload["text"]
    source_language_code = payload.get("source_language_code", "auto")  # 'auto' for automatic detection
    target_language_code = payload["target_language_code"]

    translate_client = get_translate_client(config.get("region"))

    try:
        response = translate_client.translate_text(
            Text=text_to_translate,
            SourceLanguageCode=source_language_code,
            TargetLanguageCode=target_language_code
        )
        return {
            "translated_text": response["TranslatedText"],
            "source_language_code": response["SourceLanguageCode"],
            "target_language_code": response["TargetLanguageCode"]
        }
    except Exception as e:
        raise RuntimeError(f"Error translating text: {e}")

import os
from storage_client import get_comprehend_client


def summarize_asset_content(payload, config=None):
    config = config or {}
    text_to_summarize = payload["text"]
    language_code = payload.get("language_code", "en")  # Default to English

    comprehend_client = get_comprehend_client(config.get("region"))

    # Comprehend's `detect_key_phrases` or `detect_entities` can be used as a proxy for summarization
    # For a true summarization, often a more advanced NLP model or service would be used.
    # Here, we'll extract key phrases as a form of content summarization.
    try:
        response = comprehend_client.detect_key_phrases(
            Text=text_to_summarize,
            LanguageCode=language_code
        )
        key_phrases = [phrase["Text"] for phrase in response["KeyPhrases"]]
        return {"key_phrases": key_phrases}
    except Exception as e:
        raise RuntimeError(f"Error summarizing asset content with Comprehend: {e}")
